/* chars: →　「」一不中串交以伺但作例個倒候偵儲入全共再出刪到功加動勿匯卡取叫可台名呼單器回圖在外太失字存完定密將對就已常序式弱強待後得憶成或扣找拿按掃接描操放敗數新斷易是更最會有服期未本束查模機檢櫃次沒法洽測源準為無版球生產異的盤確碼示稍稱穩第系結統網緒線置自號裝複要訊記設詢試認誤請讀資路輸近返這連過選部重錯鏡長閉開關附除電需靠韌項領頭顆體點，： */
